.fmcg-sim-container {
  padding: 20px;
  background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  max-width: 1100px;
  margin: 0 auto;
}
.fmcg-sim-container .fmcg-sim-header {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 60%, #0f3460 100%);
  color: white;
  padding: 28px 32px;
  border-radius: 18px;
  margin-bottom: 24px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.fmcg-sim-container .fmcg-company-badge {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 3px;
  color: #a8d8ea;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.fmcg-sim-container .fmcg-sim-header h1 {
  margin: 0 0 4px 0;
  font-size: 1.6rem;
  font-weight: 700;
  color: white;
}
.fmcg-sim-container .fmcg-subtitle {
  margin: 0;
  font-size: 0.85rem;
  color: #a8d8ea;
  opacity: 0.9;
}
.fmcg-sim-container .fmcg-period-bar {
  background: rgba(255,255,255,0.1);
  border-radius: 10px;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  color: white;
  white-space: nowrap;
  display: flex;
  gap: 6px;
  align-items: center;
}
.fmcg-sim-container .fmcg-alert-banner {
  background: linear-gradient(135deg, #fff3cd, #ffe8a1);
  border: 2px solid #f39c12;
  border-radius: 12px;
  padding: 14px 20px;
  margin-bottom: 20px;
  display: flex;
  gap: 10px;
  align-items: flex-start;
  font-weight: 600;
  color: #7d5c00;
  box-shadow: 0 2px 8px rgba(243,156,18,0.2);
}
.fmcg-sim-container .fmcg-alert-icon { font-size: 1.2rem; }
.fmcg-sim-container .fmcg-section-title {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #6c757d;
  margin: 0 0 12px 2px;
}
.fmcg-sim-container .fmcg-portfolio-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 28px;
}
.fmcg-sim-container .fmcg-pcard {
  background: white;
  border-radius: 14px;
  padding: 20px 18px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.08);
  text-align: center;
  transition: transform 0.2s ease;
}
.fmcg-sim-container .fmcg-pcard:hover { transform: translateY(-3px); }
.fmcg-sim-container .fmcg-pcard-total {
  border-left: 4px solid #0f3460;
}
.fmcg-sim-container .fmcg-pcard-label {
  font-size: 0.78rem;
  color: #6c757d;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
}
.fmcg-sim-container .fmcg-pcard-value {
  font-size: 1.9rem;
  font-weight: 700;
  color: #1a1a2e;
}
.fmcg-sim-container .fmcg-brand-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  margin-bottom: 28px;
}
.fmcg-sim-container .fmcg-brand-card {
  background: white;
  border-radius: 14px;
  padding: 18px 16px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.08);
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease;
}
.fmcg-sim-container .fmcg-brand-card:hover { transform: translateY(-3px); }
.fmcg-sim-container .fmcg-card-vive { border-top: 4px solid #3498db; }
.fmcg-sim-container .fmcg-card-nativa { border-top: 4px solid #27ae60; }
.fmcg-sim-container .fmcg-card-forte { border-top: 4px solid #e74c3c; }
.fmcg-sim-container .fmcg-brand-tag {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  border-radius: 20px;
  padding: 3px 10px;
  display: inline-block;
  margin-bottom: 8px;
}
.fmcg-sim-container .fmcg-tag-cow { background: #dbeafe; color: #1e40af; }
.fmcg-sim-container .fmcg-tag-star { background: #dcfce7; color: #166534; }
.fmcg-sim-container .fmcg-tag-dog { background: #fee2e2; color: #991b1b; }
.fmcg-sim-container .fmcg-brand-name {
  margin: 0 0 12px 0;
  font-size: 1.4rem;
  font-weight: 800;
  color: #1a1a2e;
  letter-spacing: 1px;
}
.fmcg-sim-container .fmcg-brand-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.fmcg-sim-container .fmcg-bmetric {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #f8f9fa;
  border-radius: 8px;
  padding: 8px 10px;
  flex: 1;
  min-width: 60px;
}
.fmcg-sim-container .fmcg-bmetric-wide { flex: 2; min-width: 100px; }
.fmcg-sim-container .fmcg-bmetric span {
  font-size: 0.65rem;
  color: #6c757d;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 3px;
}
.fmcg-sim-container .fmcg-bmetric strong {
  font-size: 1rem;
  color: #1a1a2e;
  font-weight: 700;
}
.fmcg-sim-container .fmcg-decision-panel {
  background: white;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.08);
  margin-bottom: 24px;
}
.fmcg-sim-container .fmcg-decision-panel h3 {
  margin: 0 0 4px 0;
  font-size: 1.1rem;
  font-weight: 700;
  color: #1a1a2e;
}
.fmcg-sim-container .fmcg-budget-note {
  color: #6c757d;
  font-size: 0.85rem;
  margin-bottom: 20px;
}
.fmcg-sim-container .fmcg-decision-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 20px;
}
.fmcg-sim-container .fmcg-decision-section {
  background: #f8f9fa;
  border-radius: 12px;
  padding: 16px;
}
.fmcg-sim-container .fmcg-decision-section h4 {
  margin: 0 0 14px 0;
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #495057;
}
.fmcg-sim-container .fmcg-input-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}
.fmcg-sim-container .fmcg-input-row label {
  font-size: 0.82rem;
  font-weight: 600;
  color: #343a40;
  min-width: 150px;
  flex-shrink: 0;
}
.fmcg-sim-container .fmcg-input-row input[type='number'],
.fmcg-sim-container .fmcg-input-row select {
  width: 80px;
  padding: 6px 8px;
  border: 1px solid #ced4da;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  color: #1a1a2e;
  flex-shrink: 0;
}
.fmcg-sim-container .fmcg-input-row select { width: 140px; }
.fmcg-sim-container .fmcg-hint {
  font-size: 0.72rem;
  color: #6c757d;
  font-style: italic;
}
.fmcg-sim-container .fmcg-derived-row { opacity: 0.85; }
.fmcg-sim-container .fmcg-derived-value {
  font-size: 1.1rem;
  font-weight: 700;
  color: #27ae60;
  min-width: 50px;
}
.fmcg-sim-container .fmcg-btn-row {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
}
.fmcg-sim-container .fmcg-sim-history { margin-bottom: 24px; overflow-x: auto; }
.fmcg-sim-container .fmcg-charts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 20px;
  margin-bottom: 20px;
}
.fmcg-sim-container .fmcg-chart-box {
  background: white;
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.08);
  height: 280px;
  position: relative;
}
@media (max-width: 768px) {
  .fmcg-sim-container .fmcg-sim-header { flex-direction: column; align-items: flex-start; }
  .fmcg-sim-container .fmcg-brand-grid { grid-template-columns: 1fr; }
  .fmcg-sim-container .fmcg-portfolio-cards { grid-template-columns: repeat(2, 1fr); }
  .fmcg-sim-container .fmcg-input-row label { min-width: 120px; }
}
/* --- v1.1.0: localized completion / debrief (append-only) --- */
.fmcg-cm { max-width: 640px; margin: 0 auto; padding: 8px 4px; font-family: inherit; }
.fmcg-cm-head { font-size: 1.15rem; font-weight: 700; color: #2c3e50; margin-bottom: 6px; }
