(function() {
    'use strict';

    class FMCGAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Brand Portfolio P&L';
            this.version = '1.1.0';
            this.TOTAL_BUDGET = 5000000;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalMargin: 0,
                    viveBaseline: 1050000,
                    vivePrice: 8.0,
                    viveEquity: 72,
                    viveEquityBoost: 0,
                    viveShare: 28.0,
                    nativaBaseline: 178000,
                    nativaPrice: 18.0,
                    nativaEquity: 81,
                    nativaEquityBoost: 0,
                    nativaShare: 8.0,
                    retailRetaliation: false,
                    forteBaseline: 109000,
                    fortePrice: 11.0,
                    forteEquity: 54,
                    forteEquityBoost: 0,
                    forteShare: 4.0,
                    viveMarginHistory: [],
                    nativaMarginHistory: [],
                    forteMarginHistory: [],
                    totalMarginHistory: [],
                    viveEquityHistory: [],
                    nativaEquityHistory: [],
                    forteEquityHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    viveBudget: 40,
                    nativaBudget: 40,
                    viveTrade: 30,
                    nativaTrade: 20,
                    nativaBrand: 60,
                    nativaDTC: 5,
                    forteDecision: 1
                };
            }
            var self = this;
            setTimeout(function() { self._updateForteDerived(); }, 200);
        }

        validateDecisions(decisions) {
            var viveBudgetEl = document.getElementById('viveBudgetInput');
            var nativaBudgetEl = document.getElementById('nativaBudgetInput');
            var viveTradeEl = document.getElementById('viveTradeInput');
            var nativaTradeEl = document.getElementById('nativaTradeInput');
            var nativaBrandEl = document.getElementById('nativaBrandInput');
            var nativaDTCEl = document.getElementById('nativaDTCInput');
            var forteDecisionEl = document.getElementById('forteDecisionInput');

            if (viveBudgetEl) decisions.viveBudget = parseInt(viveBudgetEl.value) || 40;
            if (nativaBudgetEl) decisions.nativaBudget = parseInt(nativaBudgetEl.value) || 40;
            if (viveTradeEl) decisions.viveTrade = parseInt(viveTradeEl.value) || 30;
            if (nativaTradeEl) decisions.nativaTrade = parseInt(nativaTradeEl.value) || 20;
            if (nativaBrandEl) decisions.nativaBrand = parseInt(nativaBrandEl.value) || 60;
            if (nativaDTCEl) decisions.nativaDTC = parseInt(nativaDTCEl.value) || 5;
            if (forteDecisionEl) decisions.forteDecision = parseInt(forteDecisionEl.value);

            var fortePct = 100 - decisions.viveBudget - decisions.nativaBudget;
            if (fortePct < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_over_100'), 'warning'
                );
                return false;
            }
            if (decisions.viveBudget < 10 || decisions.viveBudget > 70) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('vive_budget_range'), 'warning'
                );
                return false;
            }
            if (decisions.nativaBudget < 10 || decisions.nativaBudget > 60) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('nativa_budget_range'), 'warning'
                );
                return false;
            }
            this._updateForteDerived();
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var BUDGET = this.TOTAL_BUDGET;

            var fortePct = Math.max(0, 100 - d.viveBudget - d.nativaBudget);
            var viveBudgetAmt = BUDGET * d.viveBudget / 100;
            var nativaBudgetAmt = BUDGET * d.nativaBudget / 100;
            var forteBudgetAmt = BUDGET * fortePct / 100;

            // === VIVE (Cash Cow) ===
            var viveTradeSpend = viveBudgetAmt * d.viveTrade / 100;
            var viveConsumerSpend = viveBudgetAmt - viveTradeSpend;
            var viveBrandBuild = viveConsumerSpend * 0.60;

            var viveEq = ds.viveEquity + ds.viveEquityBoost;
            viveEq -= d.viveTrade * 0.07;
            viveEq = Math.max(20, Math.min(100, viveEq));
            var viveNextBoost = Math.min(6, (viveBrandBuild / 400000) * 4);

            var viveTradeUplift = 1 + (d.viveTrade / 100) * 1.3;
            var viveEqFactor = Math.pow(viveEq / 72, 0.5);
            var viveUnits = Math.round(ds.viveBaseline * viveTradeUplift * viveEqFactor);
            var viveRevenue = viveUnits * ds.vivePrice;
            var viveGM = viveRevenue * 0.45;
            var viveCM = viveGM - viveTradeSpend - viveConsumerSpend;

            var newViveBL = ds.viveBaseline;
            if (d.viveTrade > 30) {
                newViveBL = ds.viveBaseline * (1 - (d.viveTrade - 30) * 0.004);
            }
            var newViveShare = Math.max(15, Math.min(38,
                28 + (viveEqFactor - 1) * 4 + (d.viveBudget - 40) * 0.05
            ));

            // === NATIVA (Star) ===
            var nativaTradeSpend = nativaBudgetAmt * d.nativaTrade / 100;
            var nativaConsumerSpend = nativaBudgetAmt - nativaTradeSpend;
            var nativaBrandBuild = nativaConsumerSpend * d.nativaBrand / 100;

            var nativaEq = ds.nativaEquity + ds.nativaEquityBoost;
            nativaEq -= d.nativaTrade * 0.05;
            if (d.nativaDTC > 0 && d.nativaDTC <= 15) { nativaEq += d.nativaDTC * 0.08; }
            nativaEq = Math.max(30, Math.min(100, nativaEq));
            var nativaNextBoost = Math.min(8, (nativaBrandBuild / 300000) * 5);

            var retailRet = ds.retailRetaliation;
            if (d.nativaDTC > 15 && !retailRet) {
                retailRet = true;
            } else if (retailRet && d.nativaDTC <= 10) {
                retailRet = false;
            }

            var retailPenalty = retailRet ? 0.78 : 1.0;
            var nativaTradeUplift = 1 + (d.nativaTrade / 100) * 0.9;
            var nativaEqFactor = Math.pow(nativaEq / 81, 0.7);
            var nativaUnits = Math.round(ds.nativaBaseline * nativaTradeUplift * nativaEqFactor * retailPenalty);
            var nativaRevenue = nativaUnits * ds.nativaPrice;
            var nativaGM = nativaRevenue * 0.62;
            var nativaCM = nativaGM - nativaTradeSpend - nativaConsumerSpend;

            var newNativaBL = ds.nativaBaseline;
            if (d.nativaTrade > 25) {
                newNativaBL = ds.nativaBaseline * (1 - (d.nativaTrade - 25) * 0.003);
            }
            if (d.nativaDTC > 0 && !retailRet) {
                newNativaBL *= (1 + d.nativaDTC * 0.004);
            }
            var newNativaShare = Math.max(4, Math.min(18,
                8 + (nativaEqFactor - 1) * 3 + (retailRet ? -2 : 0) + (d.nativaBudget - 40) * 0.03
            ));

            // === FORTE (Dog) ===
            var forteStrat = d.forteDecision;
            var forteCM, newForteBL, forteEq, forteNextBoost, newForteShare;

            if (forteStrat === 0) {
                var harvestRevenue = ds.forteBaseline * 0.88 * ds.fortePrice;
                var harvestGM = harvestRevenue * 0.42;
                forteCM = harvestGM - forteBudgetAmt * 0.15;
                newForteBL = ds.forteBaseline * 0.86;
                forteEq = Math.max(15, ds.forteEquity + ds.forteEquityBoost - 4);
                forteNextBoost = 0;
                newForteShare = Math.max(1, ds.forteShare - 0.6);
            } else if (forteStrat === 1) {
                var forteTradeSpend1 = forteBudgetAmt * 0.35;
                var forteConsumer1 = forteBudgetAmt - forteTradeSpend1;
                forteEq = Math.max(30, Math.min(70, ds.forteEquity + ds.forteEquityBoost - 1));
                forteNextBoost = Math.min(3, (forteConsumer1 * 0.6 / 150000) * 2);
                var forteEqFactor1 = Math.pow(forteEq / 54, 0.5);
                var forteUnits1 = Math.round(ds.forteBaseline * 1.32 * forteEqFactor1 * 0.95);
                var forteRevenue1 = forteUnits1 * ds.fortePrice;
                var forteGM1 = forteRevenue1 * 0.42;
                forteCM = forteGM1 - forteTradeSpend1 - forteConsumer1;
                newForteBL = ds.forteBaseline * 0.95;
                newForteShare = Math.max(2, ds.forteShare - 0.2);
            } else {
                var forteTradeSpend2 = forteBudgetAmt * 0.20;
                var forteConsumer2 = forteBudgetAmt - forteTradeSpend2;
                forteEq = Math.min(80, ds.forteEquity + ds.forteEquityBoost + 4);
                forteNextBoost = Math.min(7, (forteConsumer2 * 0.7 / 150000) * 4);
                var forteEqFactor2 = Math.pow(Math.max(40, forteEq) / 54, 0.8);
                var forteUnits2 = Math.round(ds.forteBaseline * 1.18 * forteEqFactor2 * 1.08);
                var forteRevenue2 = forteUnits2 * ds.fortePrice * 1.12;
                var forteGM2 = forteRevenue2 * 0.44;
                forteCM = forteGM2 - forteTradeSpend2 - forteConsumer2;
                newForteBL = ds.forteBaseline * 1.03;
                newForteShare = Math.min(8, ds.forteShare + 0.4);
            }
            forteEq = Math.max(10, Math.min(90, forteEq));

            var totalCM = viveCM + nativaCM + forteCM;
            ds.totalMargin = (ds.totalMargin || 0) + totalCM;

            var portfolioShare = newViveShare + newNativaShare + newForteShare;
            var weightedEq = (viveEq * d.viveBudget + nativaEq * d.nativaBudget + forteEq * fortePct) / 100;

            ds.viveBaseline = Math.round(newViveBL);
            ds.viveEquity = Math.round(viveEq * 10) / 10;
            ds.viveEquityBoost = viveNextBoost;
            ds.viveShare = Math.round(newViveShare * 10) / 10;

            ds.nativaBaseline = Math.round(newNativaBL);
            ds.nativaEquity = Math.round(nativaEq * 10) / 10;
            ds.nativaEquityBoost = nativaNextBoost;
            ds.nativaShare = Math.round(newNativaShare * 10) / 10;
            ds.retailRetaliation = retailRet;

            ds.forteEquity = forteEq;
            ds.forteEquityBoost = forteNextBoost || 0;
            ds.forteBaseline = Math.round(newForteBL || ds.forteBaseline * 0.92);
            ds.forteShare = Math.round(newForteShare * 10) / 10;

            ds.viveMarginHistory.push(Math.round(viveCM));
            ds.nativaMarginHistory.push(Math.round(nativaCM));
            ds.forteMarginHistory.push(Math.round(forteCM));
            ds.totalMarginHistory.push(Math.round(totalCM));
            ds.viveEquityHistory.push(ds.viveEquity);
            ds.nativaEquityHistory.push(ds.nativaEquity);
            ds.forteEquityHistory.push(ds.forteEquity);

            // --- v1.1.0 fix: persist gradebook composite every period ---
            // (was only in getPerformanceSummary; grading reads
            //  domainState.performance.overallScore, missing -> 0.0)
            var _tm = ds.totalMarginHistory.reduce(function(s, x) { return s + x; }, 0);
            var _we = Math.round(weightedEq * 10) / 10;
            var _ps = Math.round(portfolioShare * 10) / 10;
            var _marginScore = Math.min(100, (_tm / 16000000) * 100);
            var _equityScore = Math.min(100, (_we / 100) * 100);
            var _shareScore = Math.min(100, (_ps / 50) * 100);
            var _ppi = Math.round(_marginScore * 0.4 + _equityScore * 0.3 + _shareScore * 0.2 + 50 * 0.1);
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _ppi;
            ds.performance.score = _ppi;

            var self = this;
            setTimeout(function() { self._updateAlertBanner(retailRet, d.viveTrade); }, 400);

            return {
                period: state.currentPeriod,
                overallScore: _ppi,
                score: _ppi,
                viveBudget: d.viveBudget,
                nativaBudget: d.nativaBudget,
                forteBudgetPct: fortePct,
                viveCM: Math.round(viveCM),
                nativaCM: Math.round(nativaCM),
                forteCM: Math.round(forteCM),
