        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalMargin = history.reduce(function(s, r) { return s + (r.results ? r.results.totalCM || 0 : 0); }, 0);
            var lastResult = history[history.length - 1] ? history[history.length - 1].results || {} : {};
            var lastEq = lastResult.weightedEq || 60;
            var portfolioShare = lastResult.portfolioShare || 35;

            var marginScore = Math.min(100, (totalMargin / 16000000) * 100);
            var equityScore = Math.min(100, (lastEq / 100) * 100);
            var shareScore = Math.min(100, (portfolioShare / 50) * 100);
            var ppi = Math.round(marginScore * 0.4 + equityScore * 0.3 + shareScore * 0.2 + 50 * 0.1);

            var performance = 'Brand Trainee';
            if (ppi >= 65) performance = 'Brand Manager';
            if (ppi >= 78) performance = 'Brand Director';
            if (ppi >= 90) performance = 'CMO';

            var insights = [];
            if (totalMargin < 8000000) insights.push('Portfolio margin below target. Review investment concentration.');
            if (lastEq < 65) insights.push('Brand equity declined. Increase brand-building versus trade investment.');
            if (portfolioShare < 35) insights.push('Market share loss. Revisit NATIVA growth and channel strategy.');
            if (insights.length === 0) insights.push('Excellent portfolio management. You balanced P&L with long-term brand equity.');

            return { totalMargin: totalMargin, ppi: ppi, overallScore: ppi, score: ppi, performance: performance, performanceLabel: this._gradeLabel(performance), weightedEq: lastEq, portfolioShare: portfolioShare, insights: insights };
        }

        _t(key) {
