            return '' +
                '<div class="fmcg-cm">' +
                    '<div class="fmcg-cm-head">' + L('cm_title', 'Portfolio Debrief') + '</div>' +
                    '<div class="fmcg-cm-score">' + score + '<span class="fmcg-cm-score-max">/100</span></div>' +
